-- Hosbah tenant queries.
-- name: InsertDeployment :one
INSERT INTO deployments (id, team_id, app_id, server_id, number, ref, trigger, kind, status, target_release_id, created_by, track, track_reason)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('server_id'),
    (SELECT coalesce(max(d.number), 0) + 1 FROM deployments d WHERE d.app_id = sqlc.arg('app_id')),
    sqlc.arg('ref'), sqlc.arg('trigger'), sqlc.arg('kind'), 'queued', sqlc.narg('target_release_id'), sqlc.arg('created_by'),
    sqlc.narg('track'), sqlc.narg('track_reason'))
RETURNING *;

-- name: InsertAdoptDeployment :one
-- Adopting an imported app: no build ran, so the deployment is recorded already finished. For a
-- container, release_id is set right after (InsertAdoptRelease then SetDeploymentRelease); for a
-- guest or unit there is no release to point at.
INSERT INTO deployments (id, team_id, app_id, server_id, number, ref, trigger, kind, status, created_by, started_at, finished_at)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('server_id'),
    (SELECT coalesce(max(d.number), 0) + 1 FROM deployments d WHERE d.app_id = sqlc.arg('app_id')),
    sqlc.arg('ref'), sqlc.arg('trigger'), 'adopt', 'succeeded', sqlc.arg('created_by'), now(), now())
RETURNING *;

-- name: SetDeploymentRelease :exec
UPDATE deployments SET release_id = sqlc.arg('release_id'), updated_at = now() WHERE id = sqlc.arg('id');

-- name: SupersedeQueuedDeployments :many
-- A later request replaces a waiting one (a later push supersedes a queued one).
UPDATE deployments SET status = 'cancelled', error = 'superseded by a newer deployment', finished_at = now(), updated_at = now()
WHERE app_id = $1 AND team_id = $2 AND status = 'queued'
RETURNING id;

-- name: DeploymentInTeam :one
SELECT * FROM deployments WHERE id = $1 AND team_id = $2;

-- name: ListDeploymentsOfApp :many
SELECT * FROM deployments WHERE app_id = $1 AND team_id = $2 ORDER BY number DESC LIMIT $3;

-- name: CancelQueuedDeployment :execrows
UPDATE deployments SET status = 'cancelled', error = sqlc.arg('reason'), finished_at = now(), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND status = 'queued';

-- name: RequestDeploymentCancel :execrows
UPDATE deployments SET cancel_requested = true, updated_at = now() WHERE id = $1 AND team_id = $2 AND status = 'running';

-- System scope: the deploy worker.
-- name: ClaimQueuedDeployment :one
SELECT d.* FROM deployments d
WHERE d.status = 'queued'
  AND NOT EXISTS (SELECT 1 FROM deployments r WHERE r.app_id = d.app_id AND r.status = 'running')
ORDER BY d.created_at
LIMIT 1
FOR UPDATE SKIP LOCKED;

-- name: StartDeployment :execrows
UPDATE deployments SET status = 'running', started_at = coalesce(started_at, now()), updated_at = now()
WHERE id = $1 AND status = 'queued';

-- name: RunningDeployments :many
SELECT * FROM deployments WHERE status = 'running' ORDER BY created_at;

-- name: DeploymentByID :one
SELECT * FROM deployments WHERE id = $1;

-- name: SetDeploymentStep :exec
UPDATE deployments SET step = $2, updated_at = now() WHERE id = $1;

-- name: SetDeploymentTrack :exec
-- The dispatcher falls back from fast to full after app.fast_build aborts (MH-573 A7): the stored
-- track and reason are updated to match what actually ran.
UPDATE deployments SET track = sqlc.arg('track'), track_reason = sqlc.arg('track_reason'), updated_at = now()
WHERE id = sqlc.arg('id');

-- name: SetDeploymentBuild :exec
UPDATE deployments SET commit_sha = sqlc.narg('commit_sha'), commit_message = sqlc.narg('commit_message'),
    image = sqlc.narg('image'), runtime = sqlc.narg('runtime'), updated_at = now()
WHERE id = sqlc.arg('id');

-- name: FinishDeployment :execrows
UPDATE deployments SET status = sqlc.arg('status'), error = sqlc.narg('error'),
    release_id = coalesce(sqlc.narg('release_id'), release_id), finished_at = now(), updated_at = now()
WHERE id = sqlc.arg('id') AND status = 'running';

-- name: NextDeploymentLogSeq :one
-- The row lock serialises concurrent writers (the agent's events and the worker's own lines).
UPDATE deployments SET last_seq = last_seq + 1 WHERE id = $1 RETURNING last_seq, app_id;

-- name: TeamDeploymentFeed :many
-- Team scope: the team's deployments across every app, newest first, keyset-paginated on
-- (created_at, id). triggered_by_email is the account that asked (null when created_by is not
-- an account: a deploy hook or a GitHub push).
SELECT d.id, d.number, d.app_id, a.name AS app_name, a.title AS app_title, a.description AS app_description, a.color AS app_color,
    a.icon AS app_icon, l.etag AS app_logo_etag, d.server_id, s.name AS server_name, d.status, d.ref,
    d.commit_sha, d.commit_message, d.trigger, d.kind, d.step, d.error, d.started_at, u.email AS triggered_by_email, d.created_at, d.finished_at
FROM deployments d
JOIN apps a ON a.id = d.app_id AND a.team_id = d.team_id
LEFT JOIN app_logos l ON l.app_id = a.id AND l.team_id = a.team_id
LEFT JOIN servers s ON s.id = d.server_id AND s.team_id = d.team_id
LEFT JOIN users u ON u.id = d.created_by
WHERE d.team_id = sqlc.arg('team_id')
  AND (sqlc.narg('before_at')::timestamptz IS NULL OR (d.created_at, d.id) < (sqlc.narg('before_at')::timestamptz, sqlc.arg('before_id')::text))
ORDER BY d.created_at DESC, d.id DESC
LIMIT sqlc.arg('limit_rows');
